function permutation(arr) {
  const result = [];
  const used = Array(arr.length).fill(false);

  function backtrack(path) {
    if (path.length === arr.length) {
      result.push(path.slice());
      return;
    }
    for (let i = 0; i < arr.length; i++) {
      if (used[i]) continue;
      used[i] = true;
      path.push(arr[i]);
      backtrack(path);
      path.pop();
      used[i] = false;
    }
  }

  backtrack([]);
  return result;
}

